{
 "BORDRO_GUNLUK": {
  "Type": "Folder",
  "Host": "ajan1",
  "RunAs": "batch",
  "Variables": [
   {
    "MUHATAP": "ik"
   }
  ],
  "Description": "Gunluk bordro akisi",
  "BORDRO_TOPLA": {
   "Type": "Job:Command",
   "Command": "cd / && echo topla >> /var/log/app/bordro_gunluk.log",
   "Description": "Bordro girdilerini toplar"
  },
  "BORDRO_HESAPLA": {
   "Type": "Job:Command",
   "Command": "cd / && echo hesapla >> /data/tmp/bordro_hesapla.log",
   "RunAs": "finans",
   "Rerun": {
    "Times": "1",
    "Interval": "2",
    "Units": "Minutes"
   },
   "Description": "Bordro hesabi (finans hesabiyla)"
  },
  "BORDRO_ONAY": {
   "Type": "Job:Command",
   "Command": "cd / && echo onay-%%DEGER >> /var/log/app/bordro_gunluk.log",
   "Variables": [
    {
     "DEGER": "A1"
    }
   ],
   "Description": "Bordro onayi"
  },
  "BORDRO_ARSIV": {
   "Type": "Job:Command",
   "Command": "cd / && echo arsiv >> /var/log/app/bordro_gunluk.log",
   "Description": "Bordro arsivi"
  },
  "akis": {
   "Type": "Flow",
   "Sequence": [
    "BORDRO_TOPLA",
    "BORDRO_HESAPLA",
    "BORDRO_ONAY",
    "BORDRO_ARSIV"
   ]
  }
 }
}

{
 "MUHASEBE_BORDRO": {
  "Type": "Folder",
  "Host": "ajan1",
  "RunAs": "batch",
  "Description": "Muhasebe bordro akisi",
  "Variables": [],
  "MUH_WAIT": {
   "Type": "Job:Dummy",
   "Description": "BORDRO_ONAYLANDI olayını bekle",
   "Event": {
    "WaitForEvents": [
     {
      "Event": "BORDRO_ONAYLANDI"
     }
    ]
   }
  },
  "MUH_AKTAR": {
